INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter einem Broadcast?', 2, '[{"text": "Datenübertragung an alle Netzwerkgeräte", "correct": true, "because": "Rundsendung"}, {"text": "Punkt-zu-Punkt-Übertragung", "correct": false, "because": "Unicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Broadcast?', 3, '[{"text": "Alle Geräte im Netzwerk erreichen", "correct": true, "because": "Netzwerkweite Kommunikation"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Kein Sicherheitsfokus"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle nutzen Broadcast?', 5, '[{"text": "ARP", "correct": true, "because": "Address Resolution Protocol"}, {"text": "DHCP", "correct": true, "because": "IP-Adresszuweisung"}, {"text": "HTTP", "correct": false, "because": "Punkt-zu-Punkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Broadcast sendet an alle Geräte im Subnetz. b) Es wird nur in WLAN genutzt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch LAN"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Broadcast?', 4, '[{"text": "Broadcast-Adresse", "correct": false, "because": "z.B. 255.255.255.255"}, {"text": "Netzwerkprotokoll", "correct": false, "because": "Übertragung definieren"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Broadcast-Adresse 255.255.255.255 ist?', 2, '[{"text": "Ja", "correct": true, "because": "IPv4-Broadcast"}, {"text": "Nein", "correct": false, "because": "Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse wird für einen Broadcast in einem IPv4-Netzwerk verwendet?', 3, '[{"text": "255.255.255.255", "correct": true, "because": "Allgemeine Broadcast-Adresse"}, {"text": "192.168.1.1", "correct": false, "because": "Spezifische IP"}, {"text": "0.0.0.0", "correct": false, "because": "Netzwerkadresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Durchführung eines Broadcasts?', 5, '[{"text": "Broadcast-Adresse", "correct": true, "because": "Ziel definieren"}, {"text": "Netzwerkprotokoll", "correct": true, "because": "z.B. ARP"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Broadcasts werden in Switches geflutet. b) Sie sind nur für kleine Netzwerke geeignet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch große Netzwerke"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Broadcast unwichtig?', 4, '[{"text": "Broadcast-Domäne", "correct": false, "because": "Reichweite definieren"}, {"text": "Protokoll", "correct": false, "because": "Übertragung"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Broadcast über Routergrenzen hinweg gesendet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Auf Broadcast-Domäne beschränkt"}, {"text": "Ja", "correct": false, "because": "Router blockieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Broadcast?', 4, '[{"text": "Effiziente Adressauflösung", "correct": true, "because": "z.B. ARP"}, {"text": "Netzwerkweite Kommunikation", "correct": true, "because": "Alle erreichen"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Broadcasts immer Netzwerke überlasten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei übermäßigem Einsatz"}, {"text": "Ja", "correct": false, "because": "Abhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Broadcast?', 3, '[{"text": "Effiziente Nutzung", "correct": true, "because": "Vermeidet Überlastung"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Broadcasts verwenden ARP. b) Sie sind nur für IPv4 relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch IPv6 (Multicast)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein Broadcast?', 5, '[{"text": "Netzwerküberlastung", "correct": true, "because": "Hoher Traffic"}, {"text": "Sicherheitsrisiken", "correct": true, "because": "Alle empfangen"}, {"text": "Schnellere Kommunikation", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei Broadcasts?', 3, '[{"text": "Netzwerkkonfiguration", "correct": true, "because": "Broadcast-Domänen"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Broadcast eingeschränkt werden?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. VLANs"}, {"text": "Nein", "correct": false, "because": "Steuerbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool könnte ein Fachinformatiker für Broadcast-Analyse nutzen?', 4, '[{"text": "Wireshark", "correct": true, "because": "Netzwerkanalyse"}, {"text": "Photoshop", "correct": false, "because": "Grafiktool"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]');
